// ============================================================
// Node-RED Function: OrdersArray Comparator
// ============================================================
// Goal of this function:
// 1. take the current OrdersArray snapshot from OPC UA,
// 2. compare it with the previous snapshot stored in context,
// 3. detect two kinds of changes:
//    - slot / position changes,
//    - production order attribute changes,
// 4. convert detected changes into insert-ready messages,
// 5. return them on 2 outputs:
//
// Output 1 -> "PUReFloor".production_order_slot_event
// Output 2 -> "PUReFloor".production_order_event
//
// General idea:
// - first message creates a full initial snapshot,
// - next messages are compared against the previous one,
// - only detected changes are emitted.
// ============================================================



// ============================================================
// extractRelevantFields
// ============================================================
// Input:
// - one element from OrdersArray, expected in shape: { Order: {...} }
//
// What it does:
// - reads only fields needed for comparison,
// - ignores fields that are not relevant for change detection.
//
// Return:
// - flat order object with relevant fields only,
// - or null if the structure is missing / invalid.
//
// Why this function exists:
// - it gives us one normalized shape for comparison logic,
// - so later code does not need to work on raw OPC UA structure.
// ============================================================
function extractRelevantFields(orderWrapper) {
    if (!orderWrapper || !orderWrapper.Order) return null;

    const o = orderWrapper.Order;

    return {
        productionOrderID: o.productionOrderID,
        materialNumber: o.materialNumber,
        Status: o.Status,
        Actual_Quantity: o.Actual_Quantity,
        Target_Quantity: o.Target_Quantity,
        ToolsOnConveyor: o.ToolsOnConveyor,
        Delete: o.Delete
    };
}



// ============================================================
// getChangedFields
// ============================================================
// Input:
// - previous flat order object,
// - current flat order object.
//
// What it does:
// - compares both objects field by field,
// - collects names of fields whose values differ.
//
// Return:
// - array of changed field names.
//
// Why this function exists:
// - it lets us detect exactly which order attributes changed,
// - while keeping comparison logic separate from the main flow.
// ============================================================
function getChangedFields(objA, objB) {
    const changedKeys = [];
    const allKeys = new Set([...Object.keys(objA), ...Object.keys(objB)]);

    allKeys.forEach((key) => {
        if (JSON.stringify(objA[key]) !== JSON.stringify(objB[key])) {
            changedKeys.push(key);
        }
    });

    return changedKeys;
}



// ============================================================
// buildPositionMap
// ============================================================
// Input:
// - full OrdersArray snapshot.
//
// What it does:
// - builds a lookup map: productionOrderID -> array index,
// - skips empty entries where productionOrderID = 0.
//
// Return:
// - Map that tells us where a given order currently sits in the array.
//
// Why this function exists:
// - it makes position comparison easy,
// - so we can detect when an order appeared, moved or disappeared.
// ============================================================
function buildPositionMap(valueArray) {
    const map = new Map();

    valueArray.forEach((entry, index) => {
        const id = entry && entry.Order && entry.Order.productionOrderID;

        if (id && id !== 0) {
            map.set(id, index);
        }
    });

    return map;
}



// ============================================================
// MAIN INPUT + VALIDATION
// ============================================================
// What this section does:
// - reads msg.payload,
// - checks if payload has the expected OrdersArray structure,
// - loads previous snapshot from context,
// - stores current snapshot immediately for the next run.
//
// Why:
// - invalid messages should be rejected early,
// - current snapshot should always become the new baseline.
// ============================================================
const incoming = msg.payload;

if (
    !incoming ||
    !Array.isArray(incoming.value) ||
    typeof incoming.name !== "string"
) {
    node.warn("Unexpected payload structure - message skipped.");
    return null;
}

const currentArray = incoming.value;
const previousArray = context.get("previousOrdersArray") || null;

// Store current array immediately so the next incoming message
// can compare against it.
context.set("previousOrdersArray", currentArray);



// ============================================================
// FIRST MESSAGE HANDLING
// ============================================================
// What this section does:
// - handles the case where there is no previous snapshot yet.
//
// Behaviour:
// - instead of comparing, it builds a full initial snapshot,
// - emits all slot states,
// - emits all real production orders.
//
// Why:
// - after restart / reconnect we want DB to receive a usable baseline,
// - not wait for the first natural change in the machine.
// ============================================================
if (previousArray === null) {
    node.log("First message received - baseline stored and full snapshot emitted.");

    const ts = incoming.ts;
    const stationId = "production_order";

    const slotEventMessages = [];
    const productionOrderEventMessages = [];

    currentArray.forEach((entry, index) => {
        const order = entry && entry.Order ? entry.Order : null;

        // Emit full slot snapshot for every slot.
        slotEventMessages.push({
            payload: {
                ts: ts,
                station_id: stationId,
                slot_id: index,
                production_order_id: order ? Number(order.productionOrderID || 0) : 0,
                production_order_tools: order ? Number(order.ToolsOnConveyor || 0) : 0
            }
        });

        // Emit full production order snapshot only for real orders.
        if (order && Number(order.productionOrderID || 0) !== 0) {
            productionOrderEventMessages.push({
                payload: {
                    ts: ts,
                    station_id: stationId,
                    production_order_id: Number(order.productionOrderID || 0),
                    production_order_mat_id: String(order.materialNumber || ""),
                    production_order_target_q: Number(order.Target_Quantity || 0),
                    production_order_q: Number(order.Actual_Quantity || 0),
                    production_order_status: Number(order.Status || 0),
                    production_order_tools: Number(order.ToolsOnConveyor || 0)
                }
            });
        }
    });

    node.status({
        fill: "yellow",
        shape: "dot",
        text: `initial snapshot -> slot: ${slotEventMessages.length}, order: ${productionOrderEventMessages.length}`
    });

    const msg1 = slotEventMessages.length > 0 ? slotEventMessages : null;
    const msg2 = productionOrderEventMessages.length > 0 ? productionOrderEventMessages : null;

    return [msg1, msg2];
}



// ============================================================
// INTERNAL CHANGE ACCUMULATORS
// ============================================================
// What this section does:
// - creates arrays that collect detected changes before they are
//   converted into final DB-ready output messages.
//
// Why:
// - first we detect logical changes,
// - then later we convert them into output payloads.
// ============================================================
const positionChangeEvents = [];
const orderChangeEvents = [];



// ============================================================
// 1. ARRAY POSITION CHANGE DETECTION
// ============================================================
// What this section does:
// - compares previous and current order positions in the array.
//
// Detects:
// - order appeared in array,
// - order moved to another slot,
// - order disappeared from array.
//
// Why:
// - slot table should reflect actual slot state changes over time.
// ============================================================
const prevPositionMap = buildPositionMap(previousArray);
const currPositionMap = buildPositionMap(currentArray);

// Detect orders that are new or moved.
currPositionMap.forEach((currentIndex, productionOrderID) => {
    const previousIndex = prevPositionMap.get(productionOrderID);

    if (previousIndex === undefined || previousIndex !== currentIndex) {
        const order = currentArray[currentIndex].Order;

        positionChangeEvents.push({
            type: "arrayPositionChange",
            previousPosition: previousIndex !== undefined ? previousIndex : null,
            currentPosition: currentIndex,
            productionOrderID: order.productionOrderID,
            ToolsOnConveyor: order.ToolsOnConveyor
        });
    }
});

// Detect orders that disappeared from the array.
prevPositionMap.forEach((prevIndex, productionOrderID) => {
    if (!currPositionMap.has(productionOrderID)) {
        const order = previousArray[prevIndex].Order;

        positionChangeEvents.push({
            type: "arrayPositionChange",
            previousPosition: prevIndex,
            currentPosition: null,
            productionOrderID: order.productionOrderID,
            ToolsOnConveyor: order.ToolsOnConveyor
        });
    }
});



// ============================================================
// 2. PRODUCTION ORDER ATTRIBUTE CHANGE DETECTION
// ============================================================
// What this section does:
// - compares order attributes at the same array index,
// - works slot-by-slot, not productionOrderID-by-productionOrderID.
//
// Detects:
// - orderAdded   -> slot was empty before, now contains a real order,
// - orderUpdated -> slot already had an order, but relevant fields changed.
//
// Why:
// - we want to know when the order data itself changed,
// - not only when the order changed position.
// ============================================================
currentArray.forEach((currentEntry, index) => {
    const currentFields = extractRelevantFields(currentEntry);

    // Ignore empty or invalid slots.
    if (!currentFields || currentFields.productionOrderID === 0) {
        return;
    }

    const previousEntry = previousArray[index] || null;
    const previousFields = extractRelevantFields(previousEntry);

    // Slot was empty before, now contains a real order.
    if (!previousFields) {
        orderChangeEvents.push({
            type: "productionOrderChange",
            changeKind: "orderAdded",
            arrayIndex: index,
            changedFields: Object.keys(currentFields),
            previousValues: null,
            currentValues: currentFields
        });
        return;
    }

    const changedFields = getChangedFields(previousFields, currentFields);

    if (changedFields.length > 0) {
        const previousValues = {};
        const currentValues = {};

        changedFields.forEach((key) => {
            previousValues[key] = previousFields[key];
            currentValues[key] = currentFields[key];
        });

        orderChangeEvents.push({
            type: "productionOrderChange",
            changeKind: "orderUpdated",
            arrayIndex: index,
            changedFields: changedFields,
            previousValues: previousValues,
            currentValues: currentValues
        });
    }
});



// ============================================================
// BUILD OUTPUT 1 -> production_order_slot_event
// ============================================================
// What this section does:
// - converts internal position-change events into insert-ready
//   messages for production_order_slot_event.
//
// Important rule:
// - when an order moves, we emit:
//   1) new state of the current slot,
//   2) new state of the previous slot after the move.
//
// Why:
// - table should represent actual slot state after the change,
// - not only movement metadata.
// ============================================================
const ts = incoming.ts;
const stationId = "production_order";

const slotEventMessages = [];
const productionOrderEventMessages = [];

positionChangeEvents.forEach((event) => {
    // Emit current slot state after appearance / move.
    if (event.currentPosition !== null) {
        const currentEntry = currentArray[event.currentPosition];
        const currentOrder = currentEntry && currentEntry.Order ? currentEntry.Order : null;

        slotEventMessages.push({
            payload: {
                ts: ts,
                station_id: stationId,
                slot_id: event.currentPosition,
                production_order_id: currentOrder ? Number(currentOrder.productionOrderID || 0) : 0,
                production_order_tools: currentOrder ? Number(currentOrder.ToolsOnConveyor || 0) : 0
            }
        });
    }

    // Emit previous slot state after disappearance / move.
    if (event.previousPosition !== null) {
        const previousSlotNowEntry = currentArray[event.previousPosition];
        const previousSlotNowOrder = previousSlotNowEntry && previousSlotNowEntry.Order ? previousSlotNowEntry.Order : null;

        slotEventMessages.push({
            payload: {
                ts: ts,
                station_id: stationId,
                slot_id: event.previousPosition,
                production_order_id: previousSlotNowOrder ? Number(previousSlotNowOrder.productionOrderID || 0) : 0,
                production_order_tools: previousSlotNowOrder ? Number(previousSlotNowOrder.ToolsOnConveyor || 0) : 0
            }
        });
    }
});



// ============================================================
// BUILD OUTPUT 2 -> production_order_event
// ============================================================
