    const index = event.arrayIndex;
    const currentEntry = currentArray[index];
    const currentFields = extractRelevantFields(currentEntry);

    if (!currentFields || currentFields.productionOrderID === 0) {
        return;
    }

    productionOrderEventMessages.push({
        payload: {
            ts: ts,
            station_id: stationId,
            production_order_id: Number(currentFields.productionOrderID || 0),
            production_order_mat_id: String(currentFields.materialNumber || ""),
            production_order_target_q: Number(currentFields.Target_Quantity || 0),
