// Detect duplicate productionOrderID values inside one OrdersArray snapshot.
// This node is only for observation:
// - it updates duplicate counter in flow context
// - it stores timestamp of the last detected duplicate
// - it shows node status
// - it does not send messages further

const incoming = msg.payload;

if (!incoming || !Array.isArray(incoming.value)) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "invalid payload"
    });
    return null;
}

const valueArray = incoming.value;
const seenIds = new Set();
const duplicateIds = new Set();

// scan current OrdersArray and detect duplicated non-zero productionOrderID values
valueArray.forEach((entry) => {
    const order = entry && entry.Order ? entry.Order : null;
    const orderId = order ? Number(order.productionOrderID || 0) : 0;

    if (orderId === 0) {
        return;
    }

    if (seenIds.has(orderId)) {
        duplicateIds.add(orderId);
    } else {
        seenIds.add(orderId);
    }
});

// load current duplicate stats from flow
const duplicateStats = flow.get("duplicate_order_id_stats") || {
    duplicate_count_total: 0,
    last_duplicate_ts: null
};

// update stats only if duplicates exist in current message
if (duplicateIds.size > 0) {
    duplicateStats.duplicate_count_total += 1;
    duplicateStats.last_duplicate_ts = incoming.ts || null;

    flow.set("duplicate_order_id_stats", duplicateStats);

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicates detected | total: ${duplicateStats.duplicate_count_total} | last: ${duplicateStats.last_duplicate_ts}`
    });

    return null;
}

// no duplicates detected in current message
node.status({
    fill: "green",
    shape: "dot",
    text: "no duplicates detected"
});

return null;

